import{_ as r,a as o,b as a,c as i}from"./chunks/3d79b4b8ff11e50f66b6.BOiUQD-x.js";import{_ as l,C as n,o as s,c as m,j as e,a as h,E as u,a6 as d}from"./chunks/framework.CnPv4DE1.js";const y=JSON.parse('{"title":"如何用 AI 记住你读过的一切","description":"","frontmatter":{"title":"如何用 AI 记住你读过的一切","originalTitle":"How To Remember Everything You Read With AI","date":"2025-04-12","originalUrl":"https://thedankoe.com/letters/how-to-remember-everything-you-read-with-ai/","minutes":13,"sourceHash":"4b00b2907f78ebb412a26d4ffd161c04bb8d6da82e787a94d593fef805d29ff0","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-remember-everything-you-read-with-ai/"}]]},"headers":[],"relativePath":"letters/how-to-remember-everything-you-read-with-ai.md","filePath":"letters/how-to-remember-everything-you-read-with-ai.md"}'),c={name:"letters/how-to-remember-everything-you-read-with-ai.md"};function g(b,p,A,f,q,I){const t=n("ArticleMeta");return s(),m("div",null,[p[0]||(p[0]=e("h1",{id:"如何用-ai-记住你读过的一切",tabindex:"-1"},[h("如何用 AI 记住你读过的一切 "),e("a",{class:"header-anchor",href:"#如何用-ai-记住你读过的一切","aria-label":'Permalink to "如何用 AI 记住你读过的一切"'},"​")],-1)),u(t),p[1]||(p[1]=d('<p><a href="https://www.youtube.com/embed/0OEtXlPtyYk?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>起初，我很生气。</p><p>现在，我只是替这个人感到难过：</p><p><img src="'+r+'" alt=""></p><p>截图</p><p>他说的话背后确实有一些真相，但那是因为大多数人，总体而言，根本不知道怎么读书。</p><p>不是因为他们不识字，而是因为他们是在一种普鲁士式的教育体制中学会读书的——这个体制的设计初衷，就是通过以下方式培养出听话的士兵、顺从的公民、公职人员和守规矩的工人：</p><ul><li>强制出勤</li><li>教师培训</li><li>国家统一课程和考试</li><li>按年龄分班</li><li>年级的概念</li></ul><p>对大多数人来说，阅读是一种<em>表演性</em>行为。</p><p>他们读书是为了给某个“考试”找特定的信息，不管是学校的考试，还是人生的考试。</p><p>他们读书是为了向别人炫耀自己完成了某件事，就像有些人炫耀自己一年读了并且“记住了”52本书的信息一样。</p><p>他们回避难懂的书，因为如果读不懂，那读它还有什么意义？</p><p>事情是这样的。</p><p>你读书不是为了找一个特定的答案。</p><p>那太蠢了。你为什么要花8个小时读一本书，就为了找到几个步骤来完成某件事，而你明明可以在谷歌、Reddit，或者现在的AI里打个问题就能得到？</p><p>如果你需要弄清楚怎样才能更高效，或者怎样创业，那读一本关于这个主题的书，应该是你最不该去的地方（如果你是真的想学到东西，而不是通过读这本书本身来让自己感觉在进步）。</p><p>如果你是想对某件事获得一个大局的理解，那没问题，书确实有用，但我要说的是，聪明且有计划的调研研究，效果依然更好。</p><p>但这不意味着阅读就变得无关紧要了。</p><p>事实上，如果你想<em>成为</em>那种更高效的人、拥有自己事业的人、或者身体健康的人（而不仅仅是知道该怎么做这些事的人）——这需要行为上的改变，而这需要你从根本上重新连接你的大脑，而这不是靠搜索特定信息能得到的。</p><p>大多数人都错过了阅读能带来的那一大堆能改变人生的好处。</p><h2 id="聪明人为什么读书" tabindex="-1">聪明人为什么读书 <a class="header-anchor" href="#聪明人为什么读书" aria-label="Permalink to &quot;聪明人为什么读书&quot;">​</a></h2><p>是的，AI让你几乎能获取到世界上所有<em>已知的</em>信息。</p><p>而如果我们从AI的崛起中学到了什么，那就是：即便人们能获取到他们想要的任何答案，他们的生活依然什么都没改变。大多数人依然在做他们一直在做的事情。</p><blockquote><p>从来都不是你知道多少的问题。一直都是你要知道自己不知道多少的问题。你只能用你手上有的食材来做饭。</p></blockquote><p>现在，你<em>已经能</em>找到你需要的信息，去赚几百万美元，练出好看的身材，或者实现你人生中想要达成的任何其他事情，但即便人们知道该找什么、去哪找、以及怎么应用他们找到的信息，他们的生活也不会发生多大改变。</p><p>因为这根本不是信息问题，<em>而是身份认同问题。</em></p><p>你的身份认同体现在你每天的选择里，如果你观察大多数人，会发现他们做的事情，根本不是出于自己的意愿。他们可能会去搜索新信息，但不是为了改变生活，而是为了通过囤积信息、让自己听起来聪明或看起来不一样，来营造一种自己在进步的感觉，实际上却什么都没有真正改变。他们从小被训练去上学、找工作、日复一日重复同样的一天，持续45年，然后期望有一天能开心地退休。这些就是他们的大脑自动想要实现的目标。这些就是决定他们会注意到哪些信息重要的过滤器。他们不需要用新信息，因为他们不会产生新目标。他们生活在一种潜意识的恐惧中，害怕如果不服从，就会被部落驱逐。所以，他们一生都在追求别人的目标。</p><p>这也没什么问题，但你之所以在读这篇文章，是因为你不想变成他们那样。</p><p>这正是阅读的重要性所在。</p><p>你读书不是为了找那些已经能找到的信息。</p><p>你读书是为了探索未知，追随你的好奇心。</p><p>你读书是为了发现你以前不知道的事，那些你甚至根本没想到要用谷歌或ChatGPT去搜索的事。</p><p>你读书是为了把你的思维拓展到你从未意识到存在的地方。</p><p><em>你读书是为了通过接触那些</em><em><strong>新的想法</strong></em><em>，慢慢重新编程你是谁——而这些想法，是一个从未想过要去搜索它们的身份认同，根本无法有意搜索到的。</em></p><p>“AI让阅读变得无关紧要”这个说法，假设的前提是每个人读书都是为了找那些已经为人所知的特定信息（那些别人也能找到的信息——用AI或不用AI都行——这意味着你是可被替代的）。</p><p>所以，问题不在于你掌握了多少信息。</p><p>也不在于你用那些信息做了什么。</p><p>关键在于改变你的思维。</p><p>因为你的思维决定了你如何与现实互动。它决定了你做出的决定会带来好的人生还是坏的人生。</p><p>你的思维不会因为几个要点就改变。</p><p>它会在新的想法（无论是否可行动）填补了缺失的部分、挑战了旧的信念、或者给了你一个看待某个情境的新角度时，才会改变。</p><p>没有任何两个人读同一本书会得出完全相同的收获。</p><p>每个人都有自己的信念、目标、问题、故事和兴趣，这些都塑造了他们如何感知书中的信息。</p><p>书籍摘要这种东西已经存在了几十年，但它们没什么大用，因为它们恰恰缺失了那些让要点真正起作用的东西。</p><p>最后一点：</p><p>对可执行步骤和要点摘要的沉迷，只是廉价多巴胺和注意力涣散的另一种表现形式。</p><p>多读书。读更长的书。读那些跟你想要达成的目标毫无关系的书。</p><p>读那些人们根本不会想到要用AI来做摘要的书。</p><p>那才是真正的金矿所在。</p><p>我和其他人一样喜欢AI，喜欢它的发展方向，也每天都在用它，但如果你没法做到AI做不到的事，那你就会是那个被替代的人。</p><p>如果你让AI来做你的决定，那你就不是高能动性的人。</p><h2 id="如何借助ai读得更深" tabindex="-1">如何借助AI读得更深 <a class="header-anchor" href="#如何借助ai读得更深" aria-label="Permalink to &quot;如何借助AI读得更深&quot;">​</a></h2><blockquote><p>知识的目的是行动，而不是知识本身。——亚里士多德</p></blockquote><p>聪明人读书分两层：</p><ol><li><strong>摄取（Consumption）</strong>——他们大量吸收信息，直到感到不堪重负、理解困难为止。</li><li><strong>消化（Digestion）</strong>——他们进行更深入的研究，通过写作系统性地反思所学，并试图通过行动把各个点连接起来。</li></ol><p>第一个问题是，很少有人真正在读书。</p><p>第二个问题是，他们读的时候，根本一点都记不住。</p><p>第三个问题是，人们不喜欢不适感，所以他们不读难懂的书。</p><p>第四个问题是，由于人们没有提升自己能够理解的知识复杂度，他们就没能力应对更具挑战性的情境……而那些情境，才是通往超越表面且短暂成功的关键。他们到了50岁，智力成熟度还停留在15岁。</p><p>现在，AI没法替你读一本书，但它能帮你在阅读的过程中加深理解。</p><p>同理，AI也没法替你行动，但它能帮你揭示出你的局限性信念和盲点，让你在迈向未来时拥有更清晰的认识。</p><p>大多数人用AI把书籍、播客和视频压缩成可执行的步骤——剥离掉那些能真正改变你思维方式的语境——而你要用AI做恰恰相反的事，这会让它变得更加强大。</p><h3 id="第一步-摄取——把ai当作你的阅读伙伴" tabindex="-1">第一步：摄取——把AI当作你的阅读伙伴 <a class="header-anchor" href="#第一步-摄取——把ai当作你的阅读伙伴" aria-label="Permalink to &quot;第一步：摄取——把AI当作你的阅读伙伴&quot;">​</a></h3><p>大多数人读书是为了尽可能多地记住内容，因为这是他们在学校被训练出来的阅读方式。</p><p>他们不知道还有别的方式。</p><p>但事情是这样的……你读书不是为了记住书中的每一句话。</p><p>你读书是为了改变你看待世界的方式，为构成你思维的这张概念网络增添几个新的节点，帮助你以一种更新、更复杂、更有意义的角度去看待各种情境。</p><p>这样，你就能同时完善你对成功的定义，并朝着它做出更经过计算的决策。</p><p>具体该怎么做：</p><p><strong>1）在类似 Z-library 的网站上下载任意PDF。</strong></p><p>没错，你应该为书付费，但不幸的是，要能用AI来参照书籍内容或对信息做任何处理，你都需要一份PDF。如果你下载了PDF，我建议你再买一本纸质书，一是支持作者，二是可以放在书架上，为家里增添点氛围。书籍能为你的家营造出一种感觉。</p><p>我自己有一个Z-library的Telegram机器人，我可以输入任何书名，它就会吐出可供下载的PDF。超级简单。</p><p>你可以<a href="https://www.reddit.com/r/zlibrary/wiki/index/access/" target="_blank" rel="noreferrer">点这里查看具体做法</a>，往下滚动到“如何通过你的个人Telegram机器人访问Zlibrary”那一节。</p><p>要小心的是，如果你直接用谷歌搜索，会遇到很多不良分子。</p><p><strong>2）把PDF拖入</strong> <a href="https://kortex.co/" target="_blank" rel="noreferrer"><strong>Kortex</strong></a> <strong>，将它添加为一个来源。</strong></p><p>这样，这本书就会被添加到你的资料库里，你随时都能用AI来查阅参考。</p><p>然后，前往 Chat &gt; Be My Reading Companion（成为我的阅读伙伴）。</p><p><img src="'+o+'" alt=""></p><p>把所有占位文本替换成“帮我理解我正在读的这本书”，然后点击发送。</p><p>我推荐用 Gemini 2 来做这件事，因为你会需要处理大量的上下文内容。</p><p><strong>注意</strong>：你不必用Kortex来做这件事。你可以把PDF上传到任何支持PDF的AI工具，然后在读的过程中向它提问。但是，我们的工具是为帮助你深入理解而专门优化的——而且你可以把回答或摘要保存为文档，供之后在其他对话中查阅或参考。</p><p>当你开始读这本书时，你可以把所有笔记都放进这个对话里，只要想深入探讨某个概念，随时提问。</p><p>现在，关于阅读本身，给你几点建议：</p><ul><li>如果一本书没能引起你的兴趣，你大概学不到什么，所以可以放弃它。</li><li>你不是在跟时间赛跑赶着读完一本书，事实上，读得越慢越好。如果需要的话，花一两年读完都没关系。</li><li>你可以同时读多本书。我经常同时读3本书加一本有声书，来回切换。你会惊讶于自己能建立起多少联系。</li><li>建立一个阅读仪式。每天至少30分钟。可以在日常散步时听有声书，或者把你在读的书随手放在家里各处，这样你就会拿起书，而不是刷手机。</li></ul><p>对于这个“摄取”层面的阅读，重点是把这本书读完，对想深入理解的部分在AI对话里做一些笔记，然后让这些想法在你脑海中慢慢发酵。</p><p>当你的大脑因好奇或兴奋而被点亮时，那就是好的多巴胺在告诉你：该深入下去了。</p><p>当你感受到这种感觉时，回到上面提到的AI对话，开始提问。</p><p>等你感觉自己理解了，再回去继续读。</p><h3 id="第二步-消化——用ai来探索与反思" tabindex="-1">第二步：消化——用AI来探索与反思 <a class="header-anchor" href="#第二步-消化——用ai来探索与反思" aria-label="Permalink to &quot;第二步：消化——用AI来探索与反思&quot;">​</a></h3><p>要完全消化一本书的思想，所需的时间远比一个周末就能读完这本书要长得多。</p><p>有些想法甚至需要好几年才能真正弄明白。</p><p>在我的人生中，曾经有那么几次，某个洞见并没有立刻击中我，而是直到我积累了足够的经验之后，它才突然一下子说通了。</p><p>而这，正是关键所在……</p><p>大多数人几乎记不住自己读过的内容，因为他们看不出这些内容和自己生活有什么关系。他们无法把书中的经验教训&quot;整合&quot;进自己的生活，以至于他们&quot;需要&quot;记住书里的每一句话，因为它并没有&quot;反映&quot;在他们的日常行动中。</p><p>如果某个东西已经深深融入了你的一部分，你根本不需要死记硬背那些句子。</p><p>所以，在阅读的消化层面，你有几个选择。</p><p><strong>1）探索一个主题的各种关联，以此锚定你的理解。</strong></p><p>提醒一下：阅读的目的是通过身份改变来实现行为改变。</p><p>当你发现那些能让书中的经验教训在你脑中&quot;咔嗒&quot;一声接通的关联时，积极的行为改变就发生了。</p><p>所以，你可以在 Kortex 里使用&quot;理解一个主题或想法&quot;（Make Sense Of A Topic Or Idea）这个工作流。</p><p><img src="'+a+'" alt=""></p><p>这个工作流旨在：</p><ul><li>针对你的个人目标、价值观和处境提出几个澄清性问题</li><li>帮助把这个概念简化到一个12岁孩子都能理解的程度</li><li>给出把这个经验教训落实到你生活中的具体、实用的方法</li><li>描述你生活中可能出现的结果，以及需要留意的障碍</li></ul><p>这为学习增添了一个全新的层面，而这个层面很少有人教授或谈论。</p><p>更进一步，你可以把上一次AI对话的回复保存为一份文档，并在这次新对话中引用它，帮助你理解它。</p><p><strong>2）把知识用于行动，而不是仅仅当作知识本身。</strong></p><p>大多数人并不需要更多的动力，他们需要的是更多的清晰度。</p><p>你已经有了目标和野心，但你从未去追求它们，因为A点（你现在所在的位置）和B点（你想到达的位置）之间需要一座由更小的目标和行动组成的桥梁，让你能够走过去。</p><p>没有这座清晰度的桥梁，焦虑和不堪重负就会开始渗透进来。</p><p>你们中许多人都熟悉我发布的<a href="https://app.kortex.co/public/document/883d9246-6dde-4794-9f54-92b8ff07d502" target="_blank" rel="noreferrer">简单人生重启规划表（Simple Life Reset planner）</a>，它能帮你把愿景拆解成优先任务，但问题是，大多数人会卡在盯着一张空白模板发呆的阶段。</p><p>人们很难去&quot;猜测&quot;自己到底想从生活中得到什么。</p><p>在我看来，最好的做法是先把你愿景和优先任务的第一版写在纸上，这样你就可以开始朝着目标不断纠错、修正。</p><p>我最终把那个模板做成了 <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a> 里的&quot;人生重启地图&quot;（Life Reset Map）工作流，它会对你进行访谈，帮你创建愿景、计划和任务。</p><p>当你完成那个工作流后，它会输出你的人生重启地图，你可以把它添加为一份文档（AI消息输出下方的按钮之一），以便之后参考。</p><p><img src="'+i+'" alt=""></p><p>它的详尽程度令人惊讶。</p><p>接下来，你可以去&quot;计划&quot;（Plan）类别下的&quot;做我的清晰度教练&quot;（Be My Clarity Coach）工作流，在你朝着那些目标行动时，它会揭穿你的自我欺骗。</p><p>仅凭这一点，就能帮助你整合你所读到的大部分内容。</p><p>你会惊讶地发现，随着你的阅读，你的大脑会自动开始把某些见解和你的愿景联系起来，这会加深你学习和记住那个概念的速度。</p><p><strong>3）通过写作来综合这些想法，反思你学到的东西。</strong></p><p>费曼技巧（Feynman Technique）是物理学家理查德·费曼（Richard Feynman）普及的一种学习方法。简单来说，它是通过用简单的语言解释一个概念——就好像你在教一个毫无相关知识的人——来深刻理解这个概念：</p><ul><li><strong>选择一个概念</strong> —— 选出你想理解的主题。</li><li><strong>教它</strong> —— 用简单的语言解释这个概念，就像你在教一个孩子。</li><li><strong>找出漏洞</strong> —— 当你在清楚地解释某件事时遇到困难，就找出你理解薄弱的地方。</li><li><strong>回顾并简化</strong> —— 回到原始材料，重新学习这些概念，然后再尝试用更简单的语言解释一遍。</li></ul><p>做到这一点最好的方式就是写作。</p><p>因为我假设你在学习某个东西，是因为（1）你对它有深切的兴趣，并且（2）你想把它整合成你生活的一部分。</p><p>当你公开教授你所知道的东西（也就是在互联网上），你就打开了几种可能性：</p><ol><li>你会学得更快、更透彻，因为你有了一种强制理解的机制。</li><li>你会吸引一群和你有相似兴趣的受众（这些人就是你的人脉网络和未来的客户）。</li><li>你会为迎接工作被取代的未来建立杠杆。创作者经济就是一个被证明不会被取代的领域，尽管所有人都在大喊内容将会严重过剩。</li></ol><p>我们在之前的通讯里已经聊过很多次这个话题了，这里就不再多说了。</p><p>如果你想开始写作，并让AI引导你完成这个过程，去 Kortex Chat 里的&quot;创作&quot;（Create）类别，从任何一个帖子写作、推文串写作或通讯写作的流程中选一个开始。</p><p>针对你正在学习的这个特定主题，我推荐使用<em>YouTube、通讯或文章草稿</em>（YouTube, Newsletter, or Article Draft）这个工作流。</p><p>当它给出主题想法时，忽略它们，让它继续沿着你在之前步骤中正在学习的那个主题往下走。</p><p>然后，当它给你一个大纲时，试着仅凭这个大纲写出完整的通讯或文章。</p><p>这是你利用AI来帮助自己学习的机会。</p><p>当你在写作中卡住时，你随时可以直接问AI，让它教你如何最好地写那一部分。</p><p>&quot;我该怎么写一个吸引人的开头（hook）？&quot;</p><p>&quot;开始一个新章节最好的方式是什么？&quot;</p><p>&quot;我想写一段关于X的内容，你会怎么开头？&quot;</p><p>&quot;这是我目前写的全部内容，你会怎么接着往下写？&quot;</p><p>试试看。</p><p>看看你能走多远。</p><p>你要意识到，没有创作的消费不会带来真正的学习，而且几乎没有理由在不进行创作的情况下去消费，因为创作本来就是你消费内容的全部理由。</p><p>希望这对你有所帮助。</p><p>感谢阅读。</p><p>—— Dan</p><hr><p><a href="/en/letters/how-to-remember-everything-you-read-with-ai">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',145))])}const w=l(c,[["render",g]]);export{y as __pageData,w as default};
